const Map<String, Map<String, Object?>> featureDescTable = {'prayerBar': {'ms': 'Waktu solat sehari di bahagian bawah skrin TV.', 'en': 'The day\'s prayer times along the bottom of the TV screen.', 'keywords': [], 'ar': 'مواقيت صلاة اليوم في أسفل شاشة التلفاز.'}, 'clock': {'ms': 'Jam besar di penjuru skrin TV.', 'en': 'A large clock in the corner of the TV screen.', 'keywords': [], 'ar': 'ساعة كبيرة في زاوية شاشة التلفاز.'}, 'prayerSequenceSafety': {'ms': 'Skrin azan, iqamah dan solat sentiasa ikut urutan yang betul.', 'en': 'The azan, iqamah and prayer screens always follow the right order.', 'keywords': [], 'ar': 'شاشات الأذان والإقامة والصلاة تتبع دائمًا الترتيب الصحيح.'}, 'zone': {'ms': 'Zon JAKIM untuk waktu solat: SGR01 Gombak, Petaling dan sekitarnya.', 'en': 'The JAKIM zone for prayer times, for example SGR01 Gombak and Petaling.', 'keywords': ['jakim', 'e-solat', 'lokasi'], 'ar': 'منطقة JAKIM لمواقيت الصلاة، مثل SGR01 غومباك وبيتالينغ وما حولهما.'}, 'location': {'ms': 'Negara, zon waktu dan koordinat surau; waktu solat di luar Malaysia dikira daripadanya.', 'en': 'The country, time zone and coordinates of the surau; prayer times outside Malaysia are calculated from them.', 'keywords': ['lokasi', 'negara', 'koordinat', 'latitud'], 'ar': 'الدولة والمنطقة الزمنية وإحداثيات المصلى؛ تُحسب منها مواقيت الصلاة خارج ماليزيا.'}, 'prayerCalc': {'ms': 'Kaedah kiraan waktu solat dari koordinat surau, dan laras minit bagi setiap waktu. Kiraan setempat sentiasa menjadi sandaran bila jadual rasmi atau fail surau tiada.', 'en': 'The method that calculates prayer times from the surau coordinates, and a minute adjustment for each prayer. Local calculation is always the fallback when the official table or the surau file has no time.', 'keywords': ['kiraan', 'kaedah', 'mazhab', 'imsak'], 'ar': 'طريقة حساب مواقيت الصلاة من إحداثيات المصلى، وتعديل بالدقائق لكل صلاة. الحساب المحلي هو البديل دائمًا عند غياب الجدول الرسمي أو ملف المصلى.'}, 'prayerSources': {'ms': 'Susunan sumber waktu solat: rasmi, kiraan setempat dan fail surau.', 'en': 'The order of the prayer time sources: official, local calculation and the surau file.', 'keywords': ['sumber', 'jadual', 'fail'], 'ar': 'ترتيب مصادر مواقيت الصلاة: الرسمي والحساب المحلي وملف المصلى.'}, 'azanCountdown': {'ms': 'Kiraan detik di skrin sebelum masuk waktu.', 'en': 'A countdown on screen before the prayer time enters.', 'keywords': ['azan'], 'ar': 'عدّ تنازلي على الشاشة قبل دخول وقت الصلاة.'}, 'masukWaktu': {'ms': 'Skrin "Telah masuk waktu" ketika azan berkumandang.', 'en': 'The "Prayer time has entered" screen while the azan is called.', 'keywords': ['azan'], 'ar': 'شاشة "دخل وقت الصلاة" أثناء رفع الأذان.'}, 'iqamahCountdown': {'ms': 'Kiraan detik dari azan hingga iqamah, ikut hari dan waktu.', 'en': 'A countdown from azan to iqamah, by day and prayer.', 'keywords': ['iqamah'], 'ar': 'عدّ تنازلي من الأذان إلى الإقامة، حسب اليوم والصلاة.'}, 'solatScreen': {'ms': 'Skrin tenang dengan mesej semasa solat berjemaah. Mesej yang sama juga dipaparkan di skrin tarawih.', 'en': 'A calm screen with a message during congregational prayer. The same message also shows on the tarawih screen.', 'keywords': ['telefon bimbit'], 'ar': 'شاشة هادئة مع رسالة أثناء صلاة الجماعة. تظهر الرسالة نفسها في شاشة التراويح أيضًا.'}, 'jumaat': {'ms': 'Tempoh khutbah, iqamah dan solat Jumaat.', 'en': 'Timings for the Friday sermon, iqamah and prayer.', 'keywords': ['khutbah'], 'ar': 'مدة الخطبة والإقامة وصلاة الجمعة.'}, 'tarawih': {'ms': 'Jadual tarawih pada bulan yang dipilih.', 'en': 'The tarawih schedule in the chosen month.', 'keywords': ['ramadan'], 'ar': 'جدول التراويح في الشهر المحدد.'}, 'syurukWarning': {'ms': 'Amaran sebelum syuruk, tanda waktu Subuh hampir tamat.', 'en': 'A warning before sunrise, when Subuh time is about to end.', 'keywords': ['syuruk'], 'ar': 'تنبيه قبل الشروق، علامة اقتراب انتهاء وقت الفجر.'}, 'imsakBeep': {'ms': 'Bunyi pendek pada waktu imsak. Bunyi ini ikut suis dan kuat Bunyi amaran; jika bunyi kiraan detik azan jatuh pada minit yang sama, hanya satu bunyi berbunyi.', 'en': 'A short beep at imsak time. It follows the Warning beeps switch and volume; when the azan countdown beep falls on the same minute, only one beep plays.', 'keywords': ['puasa'], 'ar': 'صوت قصير عند وقت الإمساك. يتبع هذا الصوت مفتاح أصوات التنبيه ومستواها؛ وإذا وقع صوت العد التنازلي للأذان في الدقيقة نفسها فيُسمع صوت واحد فقط.'}, 'isyraq': {'ms': 'Peringatan solat sunat isyraq selepas syuruk.', 'en': 'A reminder of the isyraq prayer after sunrise.', 'keywords': ['syuruk'], 'ar': 'تذكير بصلاة الإشراق بعد الشروق.'}, 'dataSources': {'ms': 'Alamat e-Solat, QuranEnc, EveryAyah, Nominatim dan HadeethEnc.', 'en': 'The addresses of e-Solat, QuranEnc, EveryAyah, Nominatim and HadeethEnc.', 'keywords': ['jakim', 'url'], 'ar': 'عناوين e-Solat وQuranEnc وEveryAyah وNominatim وHadeethEnc.'}, 'firstAzanSubuh': {'ms': 'Azan awal sebelum Subuh, dimainkan dari fail audio. Dimainkan sekali sehari dan tidak diulang selepas skrin dimuat semula. Tilawah sebelum Subuh tamat apabila azan awal bermula.', 'en': 'An early azan before Subuh, played from an audio file. It plays once a day and does not replay after a reload. A recitation before Subuh ends when it starts.', 'keywords': ['azan'], 'ar': 'أذان مبكر قبل الفجر يُشغَّل من ملف صوتي. يُشغَّل مرة واحدة في اليوم ولا يُعاد بعد إعادة تحميل الشاشة. وتنتهي التلاوة قبل الفجر عند بدئه.'}, 'surauInfo': {'ms': 'Nama, logo dan orang untuk dihubungi.', 'en': 'The name, logo and contact person.', 'keywords': ['logo', 'nama'], 'ar': 'الاسم والشعار وجهة الاتصال.'}, 'hijriDate': {'ms': 'Tarikh Hijrah dan bila ia bertukar.', 'en': 'The Hijri date and when it changes.', 'keywords': ['hijrah'], 'ar': 'التاريخ الهجري ووقت تغيّره.'}, 'backgrounds': {'ms': 'Gambar latar skrin TV dan kekerapan bertukar, untuk semua tema. Gambar asal MAXCOM hanya untuk tema Default. Di Ubah suai, Ikut tema bermaksud gambar di sini (atau gambar tema yang dimuat naik) digunakan; gambar sendiri bagi sesuatu skrin menggantikannya.', 'en': 'The TV background pictures and how often they change, for every theme. The MAXCOM built-in pictures are for the Default theme only. In Ubah suai, Follow the theme means the pictures here (or the picture of an uploaded theme) are used; an own picture for a screen replaces them.', 'keywords': ['gambar'], 'ar': 'صور خلفية شاشة التلفاز وسرعة تغيّرها، لجميع القوالب. صور MAXCOM المدمجة للقالب Default فقط. في التخصيص، "حسب القالب" تعني استخدام الصور هنا (أو صورة القالب المرفوع)؛ وصورة خاصة بشاشة معينة تحلّ محلها.'}, 'autoTone': {'ms': 'Warna teks dan aksen ikut gambar latar, untuk tema Default. Warna teks atau aksen yang dipilih di Ubah suai mengatasinya.', 'en': 'Text and accent colours follow the background picture, for the Default theme. A text or accent colour chosen in Ubah suai overrides it.', 'keywords': ['warna'], 'ar': 'لون النص واللون المميّز يتبعان صورة الخلفية، للقالب Default. أما لون النص أو اللون المميّز المختار في التخصيص فيتغلب عليهما.'}, 'language': {'ms': 'Bahasa paparan skrin TV, bukan bahasa aplikasi di telefon: Bahasa Melayu, English atau العربية (Bahasa Arab). Automatik ikut lokasi: BM di Malaysia, Inggeris di negara lain. Surau di luar negara: tetapkan Lokasi surau.', 'en': 'The display language of the TV screen, not the language of the app on the phone: Bahasa Melayu, English or العربية (Arabic). Automatic follows location: BM in Malaysia, English in other countries. A surau abroad: set Surau location.', 'keywords': ['bahasa', 'arab', 'arabic'], 'ar': 'لغة عرض شاشة التلفاز، وليست لغة التطبيق على الهاتف: البهاسا الملايو أو الإنجليزية أو العربية. الوضع التلقائي حسب الموقع: البهاسا الملايو في ماليزيا والإنجليزية في الدول الأخرى. مصلى خارج ماليزيا: اضبط موقع المصلى.'}, 'orientation': {'ms': 'Skrin TV mendatar atau menegak.', 'en': 'The TV screen landscape or portrait.', 'keywords': ['mendatar', 'menegak'], 'ar': 'شاشة التلفاز أفقية أو عمودية.'}, 'kioskTemplate': {'ms': 'Tema menukar seluruh rupa skrin TV. Setiap skrin boleh diubah suai.', 'en': 'The theme changes the whole look of the TV screen. Every screen can be customised.', 'keywords': ['templat', 'tema', 'rupa', 'warna'], 'ar': 'القالب يغيّر مظهر شاشة التلفاز كله. ويمكن تخصيص كل شاشة.'}, 'themeStyle': {'ms': 'Ubah suai rupa setiap skrin bagi tema.', 'en': 'Customise the look of each screen of a theme.', 'keywords': ['tema', 'ubah suai'], 'ar': 'خصّص مظهر كل شاشة في القالب.'}, 'kuliahCard': {'ms': 'Kuliah akan datang di skrin TV.', 'en': 'Upcoming lectures on the TV screen.', 'keywords': ['kuliah'], 'ar': 'الدروس القادمة على شاشة التلفاز.'}, 'penceramahPhoto': {'ms': 'Bentuk gambar penceramah pada kad kuliah.', 'en': 'The shape of the speaker photo on the lecture card.', 'keywords': ['penceramah'], 'ar': 'شكل صورة المحاضر في بطاقة الدرس.'}, 'kitabCover': {'ms': 'Papar kulit kitab pada kad kuliah.', 'en': 'Show the book cover on the lecture card.', 'keywords': ['kitab'], 'ar': 'عرض غلاف الكتاب في بطاقة الدرس.'}, 'pengumuman': {'ms': 'Pengumuman surau di skrin TV.', 'en': 'Surau announcements on the TV screen.', 'keywords': [], 'ar': 'إعلانات المصلى على شاشة التلفاز.'}, 'ticker': {'ms': 'Teks bergerak di bahagian bawah skrin.', 'en': 'Scrolling text along the bottom of the screen.', 'keywords': [], 'ar': 'نص متحرك في أسفل الشاشة.'}, 'posters': {'ms': 'Poster bergilir di skrin TV.', 'en': 'Posters shown in turn on the TV screen.', 'keywords': [], 'ar': 'ملصقات تُعرض بالتناوب على شاشة التلفاز.'}, 'videos': {'ms': 'Video bergilir di skrin TV, dimainkan hingga tamat.', 'en': 'Videos shown in turn on the TV screen, played to the end.', 'keywords': ['rakaman', 'youtube'], 'ar': 'مقاطع فيديو تُعرض بالتناوب على شاشة التلفاز وتُشغَّل حتى نهايتها.'}, 'programKhas': {'ms': 'Program khas yang akan datang.', 'en': 'Upcoming special programmes.', 'keywords': [], 'ar': 'البرامج الخاصة القادمة.'}, 'takwim': {'ms': 'Tarikh penting Islam yang akan datang.', 'en': 'Upcoming important Islamic dates.', 'keywords': ['kalendar'], 'ar': 'التواريخ الإسلامية المهمة القادمة.'}, 'hadis': {'ms': 'Hadis bergilir di skrin TV, rawak atau pilih sendiri. Bilangan hadis sehari menentukan set harian.', 'en': 'Hadith shown in turn on the TV screen, random or chosen by you. The number per day sets the daily set.', 'keywords': [], 'ar': 'أحاديث تُعرض بالتناوب على شاشة التلفاز، عشوائيًا أو باختيارك. وعدد الأحاديث في اليوم يحدد المجموعة اليومية.'}, 'worldTimes': {'ms': 'Waktu di Makkah, Madinah dan bandar lain.', 'en': 'The time in Makkah, Madinah and other cities.', 'keywords': ['makkah'], 'ar': 'الوقت في مكة المكرمة والمدينة المنورة ومدن أخرى.'}, 'tugasan': {'ms': 'Jadual bertugas imam, bilal dan AJK.', 'en': 'The duty roster for imam, bilal and committee.', 'keywords': ['imam', 'bilal'], 'ar': 'جدول مناوبة الإمام والمؤذن وأعضاء اللجنة.'}, 'ayatCard': {'ms': 'Ayat Al-Quran pilihan dengan terjemahan.', 'en': 'A chosen Quran verse with translation.', 'keywords': ['quran'], 'ar': 'آية قرآنية مختارة مع ترجمتها.'}, 'zikirSelepasSolat': {'ms': 'Zikir di skrin selepas setiap solat.', 'en': 'Zikir on screen after each prayer.', 'keywords': [], 'ar': 'أذكار على الشاشة بعد كل صلاة.'}, 'quranReader': {'ms': 'Baca mushaf penuh di aplikasi dan skrin TV.', 'en': 'Read the full mushaf in the app and on the TV screen.', 'keywords': ['mushaf'], 'ar': 'قراءة المصحف كاملًا في التطبيق وعلى شاشة التلفاز.'}, 'tilawah': {'ms': 'Bacaan Al-Quran oleh qari pilihan.', 'en': 'Quran recitation by a chosen reciter.', 'keywords': ['qari'], 'ar': 'تلاوة القرآن بصوت قارئ مختار.'}, 'beeps': {'ms': 'Suis dan kuat bunyi amaran sebelum azan dan iqamah, bunyi imsak dan bunyi syuruk. Jika suis dimatikan atau kuat ialah 0, bunyi imsak, bunyi syuruk dan azan pertama Subuh turut senyap. Azan pertama berhenti apabila kiraan detik azan Subuh bermula, atau pada waktu Subuh.', 'en': 'The switch and volume of the warning beeps before azan and iqamah, the imsak beep and the syuruk beep. With the switch off or the volume at 0, the imsak beep, the syuruk beep and the first Subuh azan are silent too. The first azan stops when the Subuh azan countdown starts, or at Subuh.', 'keywords': ['azan', 'iqamah'], 'ar': 'مفتاح ومستوى أصوات التنبيه قبل الأذان والإقامة، وصوت الإمساك وصوت الشروق. إذا أُوقف المفتاح أو كان المستوى 0، يسكت أيضًا صوت الإمساك وصوت الشروق وأذان الفجر الأول. ويتوقف الأذان الأول عندما يبدأ العد التنازلي لأذان الفجر، أو عند الفجر.'}, 'liveOnKiosk': {'ms': 'Kuliah yang sedang disiarkan, terus di skrin TV. Jika dimatikan, siaran langsung tidak dapat dimulakan langsung, termasuk siaran ke YouTube sahaja.', 'en': 'The lecture being broadcast, shown directly on the TV screen. When off, no live broadcast can start, including one to YouTube only.', 'keywords': ['siaran'], 'ar': 'الدرس المبثوث حاليًا، يظهر مباشرة على شاشة التلفاز. إذا أُوقف، لا يمكن بدء أي بث مباشر، بما في ذلك البث إلى YouTube فقط.'}, 'liveYoutube': {'ms': 'Siarkan kuliah ke saluran YouTube surau sendiri.', 'en': 'Broadcast the lecture to the surau\'s own YouTube channel.', 'keywords': ['youtube'], 'ar': 'بث الدرس إلى قناة YouTube الخاصة بالمصلى.'}, 'recording': {'ms': 'Rakam kuliah ke fail di peranti. Jika Simpan rakaman di peranti dimatikan, salinan di peranti dipadam sebaik YouTube mengesahkannya.', 'en': 'Record the lecture to files on the device. When Keep the recording on the device is off, the copy on the device is deleted as soon as YouTube confirms it.', 'keywords': ['rakaman'], 'ar': 'تسجيل الدرس في ملفات على الجهاز. إذا أُوقف خيار "حفظ التسجيل على الجهاز"، تُحذف النسخة الموجودة على الجهاز فور تأكيد YouTube لها.'}, 'liveCamera': {'ms': 'Kamera luaran (RTSP) untuk siaran langsung: gambar dan audionya sendiri, dengan sumber audio lain boleh ditambah.', 'en': 'An external (RTSP) camera for the live broadcast: its picture and its own audio, with other audio sources that can be added.', 'keywords': ['rtsp', 'cctv', 'kamera', 'ip'], 'ar': 'كاميرا خارجية (RTSP) للبث المباشر: صورتها وصوتها الخاص، مع إمكانية إضافة مصادر صوت أخرى.'}, 'finance': {'ms': 'Rekod kutipan dan perbelanjaan surau.', 'en': 'Record the surau\'s collections and spending.', 'keywords': ['derma'], 'ar': 'سجل تحصيلات المصلى ومصروفاته.'}, 'tabungCard': {'ms': 'Baki tabung surau di skrin TV, paling banyak 4 tabung sehalaman. Tempoh paparan ialah masa setiap halaman. Tonjolkan tabung pertama memaparkan tabung pertama dalam susunan anda dengan besar.', 'en': 'The surau fund balances on the TV screen, at most 4 funds a page. The display time is the time of each page. Feature the first fund shows the first fund in your order large.', 'keywords': ['derma'], 'ar': 'أرصدة صناديق تبرعات المصلى على شاشة التلفاز، بحد أقصى 4 صناديق في الصفحة. مدة العرض هي وقت كل صفحة. "إبراز الصندوق الأول" يعرض الصندوق الأول في ترتيبك بحجم كبير.'}, 'calendarFeed': {'ms': 'Jadual kuliah dalam kalendar telefon jemaah.', 'en': 'The lecture schedule in the congregation\'s phone calendars.', 'keywords': ['kalendar'], 'ar': 'جدول الدروس في تقويمات هواتف المصلّين.'}, 'jemaahPage': {'ms': 'Laman web ringkas untuk jemaah. Dirancang, belum tersedia.', 'en': 'A simple web page for the congregation. Planned, not available yet.', 'keywords': [], 'ar': 'صفحة ويب بسيطة للمصلّين. مخططة، وغير متاحة بعد.'}, 'cloudSync': {'ms': 'Alamat awan MAXCOM dan selang semak perubahan.', 'en': 'The MAXCOM cloud address and how often changes are checked.', 'keywords': ['awan'], 'ar': 'عنوان سحابة MAXCOM وكل كم يُفحص التغيير.'}, 'youtubeCatchUp': {'ms': 'Muat naik rakaman bila siaran langsung terputus.', 'en': 'Upload the recording when a live broadcast was cut.', 'keywords': ['youtube'], 'ar': 'رفع التسجيل عندما ينقطع البث المباشر.'}, 'recordingCleanup': {'ms': 'Padam rakaman di peranti selepas YouTube mengesahkannya.', 'en': 'Delete recordings on the device once YouTube has confirmed them.', 'keywords': ['rakaman'], 'ar': 'حذف التسجيلات من الجهاز بعد تأكيد YouTube لها.'}, 'appLock': {'ms': 'PIN atau cap jari setiap kali MAXCOM dibuka.', 'en': 'A PIN or fingerprint every time MAXCOM is opened.', 'keywords': ['pin', 'cap jari'], 'ar': 'رمز PIN أو بصمة الإصبع في كل مرة يُفتح فيها MAXCOM.'}, 'system': {'ms': 'Amaran tiada video, tunggu awan bangun, sejarah penyelarasan.', 'en': 'The no-video warning, how long to wait for the cloud, and sync history.', 'keywords': [], 'ar': 'تنبيه غياب الفيديو، ومدة انتظار السحابة، وسجل المزامنة.'}};

